import pathlib,re
for f in sorted(pathlib.Path('/docs').glob('*.txt')):
 s=f.read_text(); pages=re.split(r'--- page (\\d+) ---',s)
 print('\\nFILE',f.name[:-4])
 for i in range(1,len(pages),2):
  lines=pages[i+1].replace('\\xa0',' ').splitlines()
  hits=[j for j,l in enumerate(lines) if re.search(r'terminat',l,re.I) and not re.search(r'upon termination|following termination|survive|expiration or termination|termination or expiration',l,re.I)]
  ranges=set()
  for j in hits:
   for k in range(max(0,j-1),min(len(lines),j+5)):ranges.add(k)
  if ranges:
   print('PAGE',pages[i]);print('\\n'.join(lines[k] for k in sorted(ranges)))
